contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The test checks: on a non-reverting voteProposal, total votes >= this caller's recorded member votes
    function run(uint proposalID) public payable {
        require(proposalID > 0);

        // Call voteProposal and capture whether it reverted
        bool reverted;
        uint256 w = c.voteProposal(proposalID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read observed recorded member votes and total votes from public getters
        uint observedMemberVotes = c.mapPIDMember_votes(proposalID, address(this)); if (__ESBMC_reverted()) return;
        uint totalVotes = c.mapPID_votes(proposalID); if (__ESBMC_reverted()) return;

        // Assert the invariant: if the call succeeded, totalVotes >= this member's recorded votes
        assert(reverted || totalVotes >= observedMemberVotes);
    }

    receive() external payable {}
}

